function render(){
  const d=devicePixelRatio||1,w=c.width/d,h=c.height/d;
  ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);
  ctx.strokeStyle='rgba(255,255,255,.035)';ctx.lineWidth=1;
  const gap=48, ox=(performance.now()/40)%gap;
  for(let x=-gap+ox;x<w;x+=gap){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke();}
  for(let y=0;y<h;y+=gap){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}
  if(running){
    const interval=60000/bpmVal, elapsed=(performance.now()-lastBeat)/interval;
    ctx.strokeStyle='rgba(255,98,56,'+(0.08+0.12*(1-Math.abs(elapsed-.5)*2))+')';
    ctx.lineWidth=1;ctx.beginPath();ctx.arc(w/2,h/2,Math.min(w,h)*(.30+elapsed*.08),0,Math.PI*2);ctx.stroke();
  }
  requestAnimationFrame(render);
}
render();
</script>

